    m.querySelector('.sy-mdev').textContent = '🎙 ' + (x.device || 'Microphone') + (x.channels > 1 ? ' · input ' + x.input + (x.chosen ? '' : ' (auto)') : '');
    m.querySelector('b').style.width = pct + '%';
