        Say.history.push({ role: 'user', text }, { role: 'assistant', text: say });
        Say.plan = null; Say.askView(); Say.state(''); Say.logPaint();
        try { Team.ctx = null; if (Hud.on) Hud.paint(); } catch (e) {}
