    const ag = M ? Object.keys(M.byAgent).map((id) => { const a = M.byAgent[id]; return '<div class="hud-r"><span data-i18n="off">' + esc(id === 'script' ? 'Automations (no model)' : (Team.agent(id) || {}).name || id) + '</span><b data-i18n="off">' + a.runs + ' · ' + a.calls + ' calls · ' + a.okRate + '% · ' + a.interventions + ' interventions</b></div>'; }).join('') : '';
    const S = E && E.settings || {};
    const setPanel = Hud.panel('efset', 'Orchestration and schedule', '<label class="hud-tick hud-opt" data-flow-no-chip><input type="checkbox" data-team-eff="skipHandoverSingle"' + (S.skipHandoverSingle ? ' checked' : '') + '> Skip the hand-over call when a delegated task has one step</label>' +
      '<form data-team="efschedule" class="hud-row" data-flow-no-chip><label class="hud-tick"><input type="checkbox" name="on"' + (S.schedule ? ' checked' : '') + '> Weekly review</label><select class="hud-sel" name="day">' + ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map((n, i) => '<option value="' + i + '"' + ((S.schedule ? S.schedule.day : 0) === i ? ' selected' : '') + '>' + n + '</option>').join('') + '</select><input class="hud-sel" type="time" name="at" value="' + esc(S.schedule ? S.schedule.at : '08:30') + '"><button type="submit" class="hud-btn ghost">Save</button></form>' +
      ((E && E.settingsHistory && E.settingsHistory.length) ? '<p class="hud-sub" data-i18n="off">Changes: ' + E.settingsHistory.slice(0, 4).map((h) => h.key + ' ' + h.from + ' → ' + h.to + ' (' + Team.when(h.at) + ')').join(' · ') + '</p>' : '') +
      '<p class="hud-sub">A scheduled review runs the same analysis and sends the top findings to your channels as a fixed message — no model. Nothing is applied without you.</p>');
