    const head = '<div class="hud-row"><button type="button" class="hud-btn" data-hud="efreview"' + (Team.efBusy ? ' disabled' : '') + '>' + (Team.efBusy ? 'Reviewing…' : (R ? 'Review again' : 'Review now')) + '</button>' + (R ? '<small class="hud-sub" data-i18n="off">last: ' + esc(Team.when(R.at)) + ' · ' + esc(R.trigger) + ' · ' + R.summary.tasks + ' tasks · ' + R.summary.findings + ' finding' + (R.summary.findings === 1 ? '' : 's') + '</small>' : '') + '</div>';
    if (!R) return Hud.panel('effind', 'Findings', head + '<p class="hud-sub">The review reads the last 30 days — every task\'s calls, tokens, retries and questions; the knowledge store and its history; skills, automations and their runs; which pages and entries replies used; edited and declined approvals — and lists what is wasting effort, with the evidence and the change that would fix it. Confirmed causes are marked apart from hypotheses.</p>');
